<?php
namespace App\Http\Controllers;
use App\Models\{Activity,Application,EthicsApplication,Institution,Student};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class DirectoryController extends Controller {
 public function calendar(Request $r){$query=Activity::orderBy('start_at');if($r->user()->hasRole('applicant'))$query->whereHas('application',fn($q)=>$q->where('applicant_id',$r->user()->id));return view('calendar',['activities'=>$query->get()]);}
 public function institutions(){return view('directory.institutions',['institutions'=>Institution::orderBy('name')->paginate(15)]);}
 public function search(Request $r){
  $term=$r->validate(['q'=>'required|min:2'])['q'];$user=$r->user();$results=collect();
  if($user->canDo('diklat.view')){$query=Application::where(fn($q)=>$q->where('number','like','%'.$term.'%')->orWhere('title','like','%'.$term.'%'));if($user->hasRole('applicant'))$query->where('applicant_id',$user->id);$query->limit(8)->get()->each(fn($row)=>$results->push(['type'=>'Pengajuan','number'=>$row->number,'title'=>$row->title,'url'=>'/applications/'.$row->id]));}
  if($user->canDo('kamkordik.view')){$query=Student::where(fn($q)=>$q->where('number','like','%'.$term.'%')->orWhere('name','like','%'.$term.'%'));if($user->hasRole('student'))$query->where('user_id',$user->id);elseif($user->hasRole('clinical-supervisor'))$query->whereHas('rotations.supervisor',fn($q)=>$q->where('user_id',$user->id));$query->limit(8)->get()->each(fn($row)=>$results->push(['type'=>'Peserta','number'=>$row->number,'title'=>$row->name,'url'=>'/kamkordik']));}
  if($user->canDo('ethics.view')){$query=EthicsApplication::where(fn($q)=>$q->where('number','like','%'.$term.'%')->orWhere('title','like','%'.$term.'%'));if($user->hasRole('applicant'))$query->where('applicant_id',$user->id);elseif($user->hasRole('ethics-reviewer'))$query->whereHas('reviews',fn($q)=>$q->where('reviewer_id',$user->id));$query->limit(8)->get()->each(fn($row)=>$results->push(['type'=>'Etik','number'=>$row->number,'title'=>$row->title,'url'=>'/ethics/'.$row->id]));}
  return view('search',compact('term','results'));
 }
 public function audits(){return view('directory.audits',['logs'=>DB::table('audit_logs')->leftJoin('users','users.id','=','audit_logs.user_id')->select('audit_logs.*','users.name as user_name')->latest('audit_logs.created_at')->paginate(20)]);}
 public function reports(Request $request){$module=$request->get('module','management');$allowed=match($module){'diklat'=>$request->user()->canDo('diklat.view'),'kamkordik'=>$request->user()->canDo('kamkordik.view'),'ethics'=>$request->user()->canDo('ethics.view'),default=>$request->user()->hasRole('super-admin')};abort_unless($allowed,403,'Anda tidak memiliki akses ke laporan modul ini.');$durations=DB::table('ethics_reviews')->whereNotNull('completed_at')->get(['assigned_at','completed_at'])->map(fn($r)=>\Carbon\Carbon::parse($r->assigned_at)->diffInDays(\Carbon\Carbon::parse($r->completed_at)));$distribution=match($module){'kamkordik'=>DB::table('students')->selectRaw('status,count(*) total')->groupBy('status')->get(),'ethics'=>DB::table('ethics_applications')->selectRaw('status,count(*) total')->groupBy('status')->get(),default=>DB::table('applications')->selectRaw('status,count(*) total')->groupBy('status')->get()};$reportTitle=match($module){'diklat'=>'Laporan Diklat Eksternal','kamkordik'=>'Laporan KAMKORDIK','ethics'=>'Laporan Komite Etik',default=>'Laporan & KPI Manajemen'};$distributionTitle=match($module){'kamkordik'=>'Distribusi Status Peserta','ethics'=>'Distribusi Status Pengajuan Etik',default=>'Distribusi Status Pengajuan Diklat'};return view('reports',['applications'=>$distribution,'income'=>$module==='diklat'||$module==='management'?DB::table('payments')->where('status','verified')->sum('amount'):0,'institutions'=>DB::table('institutions')->count(),'students'=>$module==='kamkordik'||$module==='management'?DB::table('students')->count():0,'reviews'=>$module==='ethics'||$module==='management'?($durations->avg()??0):0,'module'=>$module,'reportTitle'=>$reportTitle,'distributionTitle'=>$distributionTitle]);}
}
